func ptrFormMapping(p unsafe.Pointer, c int32) any {
	r := (*telematics.FormMapping)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return &r.Provider
	case 4:
		return &r.TemplateID
	case 5:
		return &r.TemplateName
	case 6:
		return &r.Name
	case 7:
		return &r.Description
	case 8:
		return &r.Enabled
	case 9:
		return &r.Version
	case 10:
		return &r.CreatedAt
	case 11:
		return &r.UpdatedAt
	}
	return nil
}

func valueFormMapping(p unsafe.Pointer, c int32) any {
	r := (*telematics.FormMapping)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return r.Provider
	case 4:
		return r.TemplateID
	case 5:
		if r.TemplateName == "" {
			return nil
		}
		return r.TemplateName
	case 6:
		return r.Name
	case 7:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 8:
		return r.Enabled
	case 9:
		return r.Version
	case 10:
		return r.CreatedAt
	case 11:
		return r.UpdatedAt
	}
	return nil
}

func attachFormMapping(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*telematics.FormMapping)(p)
	switch rel {
	case 0:
		r.Items = append(r.Items, (*telematics.FormMappingItem)(child))
	}
}

