func newFormSubmission() unsafe.Pointer { return unsafe.Pointer(new(telematics.FormSubmission)) }

func newNFormSubmission(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]telematics.FormSubmission, n)))
}

func ptrFormSubmission(p unsafe.Pointer, c int32) any {
	r := (*telematics.FormSubmission)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return &r.Provider
	case 4:
		return &r.ProviderSubmissionID
	case 5:
		return &r.TemplateID
	case 6:
		return &r.TemplateName
	case 7:
		return (*string)(unsafe.Pointer(&r.WorkerID))
	case 8:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 9:
		return (*string)(unsafe.Pointer(&r.ShipmentMoveID))
	case 10:
		return (*string)(unsafe.Pointer(&r.StopID))
	case 11:
		return &r.SubmittedAt
	case 12:
		return &r.Fields
	case 13:
		return &r.Applied
	case 14:
		return (*int64)(unsafe.Pointer(&r.AppliedFields))
	case 15:
		return &r.AppliedAt
	case 16:
		return &r.CreatedAt
	}
	return nil
}

func valueFormSubmission(p unsafe.Pointer, c int32) any {
	r := (*telematics.FormSubmission)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return r.Provider
	case 4:
		return r.ProviderSubmissionID
	case 5:
		return r.TemplateID
	case 6:
		if r.TemplateName == "" {
			return nil
		}
		return r.TemplateName
	case 7:
		if r.WorkerID == "" {
			return nil
		}
		return string(r.WorkerID)
	case 8:
		if r.ShipmentID == "" {
			return nil
		}
		return string(r.ShipmentID)
	case 9:
		if r.ShipmentMoveID == "" {
			return nil
		}
		return string(r.ShipmentMoveID)
	case 10:
		if r.StopID == "" {
			return nil
		}
		return string(r.StopID)
	case 11:
		return r.SubmittedAt
	case 12:
		if r.Fields == nil {
			return nil
		}
		return r.Fields
	case 13:
		return r.Applied
	case 14:
		return int64(r.AppliedFields)
	case 15:
		if r.AppliedAt == nil {
			return nil
		}
		return *r.AppliedAt
	case 16:
		return r.CreatedAt
	}
	return nil
}

