func ptrVehicleInspection(p unsafe.Pointer, c int32) any {
	r := (*telematics.VehicleInspection)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return &r.Provider
	case 4:
		return &r.ProviderDvirID
	case 5:
		return (*string)(unsafe.Pointer(&r.TractorID))
	case 6:
		return (*string)(unsafe.Pointer(&r.WorkerID))
	case 7:
		return &r.InspectionType
	case 8:
		return &r.SafetyStatus
	case 9:
		return &r.StartedAt
	case 10:
		return &r.EndedAt
	case 11:
		return &r.OdometerMeters
	case 12:
		return &r.Location
	case 13:
		return &r.Signed
	case 14:
		return (*int64)(unsafe.Pointer(&r.DefectCount))
	case 15:
		return (*int64)(unsafe.Pointer(&r.UnresolvedDefectCount))
	case 16:
		return &r.Defects
	case 17:
		return &r.CreatedAt
	}
	return nil
}

func valueVehicleInspection(p unsafe.Pointer, c int32) any {
	r := (*telematics.VehicleInspection)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return r.Provider
	case 4:
		return r.ProviderDvirID
	case 5:
		if r.TractorID == "" {
			return nil
		}
		return string(r.TractorID)
	case 6:
		if r.WorkerID == "" {
			return nil
		}
		return string(r.WorkerID)
	case 7:
		return r.InspectionType
	case 8:
		return r.SafetyStatus
	case 9:
		return r.StartedAt
	case 10:
		return r.EndedAt
	case 11:
		if r.OdometerMeters == nil {
			return nil
		}
		return *r.OdometerMeters
	case 12:
		if r.Location == "" {
			return nil
		}
		return r.Location
	case 13:
		return r.Signed
	case 14:
		return int64(r.DefectCount)
	case 15:
		return int64(r.UnresolvedDefectCount)
	case 16:
		if r.Defects == nil {
			return nil
		}
		return r.Defects
	case 17:
		return r.CreatedAt
	}
	return nil
}

