func newVehiclePosition() unsafe.Pointer { return unsafe.Pointer(new(telematics.VehiclePosition)) }

func newNVehiclePosition(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]telematics.VehiclePosition, n)))
}

func ptrVehiclePosition(p unsafe.Pointer, c int32) any {
	r := (*telematics.VehiclePosition)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.TractorID))
	case 3:
		return &r.Provider
	case 4:
		return &r.ProviderVehicleID
	case 5:
		return &r.Latitude
	case 6:
		return &r.Longitude
	case 7:
		return &r.HeadingDegrees
	case 8:
		return &r.SpeedMph
	case 9:
		return (*string)(unsafe.Pointer(&r.EngineState))
	case 10:
		return &r.FuelPercent
	case 11:
		return &r.OdometerMeters
	case 12:
		return &r.FormattedLocation
	case 13:
		return &r.RecordedAt
	case 14:
		return &r.ReceivedAt
	}
	return nil
}

func valueVehiclePosition(p unsafe.Pointer, c int32) any {
	r := (*telematics.VehiclePosition)(p)
	switch c {
	case 0:
		return string(r.OrganizationID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.TractorID)
	case 3:
		return r.Provider
	case 4:
		return r.ProviderVehicleID
	case 5:
		return r.Latitude
	case 6:
		return r.Longitude
	case 7:
		return r.HeadingDegrees
	case 8:
		return r.SpeedMph
	case 9:
		if r.EngineState == "" {
			return nil
		}
		return string(r.EngineState)
	case 10:
		if r.FuelPercent == nil {
			return nil
		}
		return *r.FuelPercent
	case 11:
		if r.OdometerMeters == nil {
			return nil
		}
		return *r.OdometerMeters
	case 12:
		if r.FormattedLocation == "" {
			return nil
		}
		return r.FormattedLocation
	case 13:
		return r.RecordedAt
	case 14:
		return r.ReceivedAt
	}
	return nil
}

func attachVehiclePosition(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*telematics.VehiclePosition)(p)
	switch rel {
	case 0:
		r.Tractor = (*tractor.Tractor)(child)
	}
}

func beforeCreateVehiclePosition(ctx context.Context, p unsafe.Pointer) error {
	return (*telematics.VehiclePosition)(p).BeforeCreate(ctx)
}

