func newWorkerHOSViolation() unsafe.Pointer {
	return unsafe.Pointer(new(telematics.WorkerHOSViolation))
}

func newNWorkerHOSViolation(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]telematics.WorkerHOSViolation, n)))
}

func ptrWorkerHOSViolation(p unsafe.Pointer, c int32) any {
	r := (*telematics.WorkerHOSViolation)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.WorkerID))
	case 3:
		return &r.ViolationType
	case 4:
		return &r.ViolationStartAt
	case 5:
		return &r.Description
	case 6:
		return &r.DurationMs
	case 7:
		return &r.DayStartAt
	case 8:
		return &r.DayEndAt
	case 9:
		return &r.DetectedAt
	}
	return nil
}

func valueWorkerHOSViolation(p unsafe.Pointer, c int32) any {
	r := (*telematics.WorkerHOSViolation)(p)
	switch c {
	case 0:
		return string(r.OrganizationID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.WorkerID)
	case 3:
		return r.ViolationType
	case 4:
		return r.ViolationStartAt
	case 5:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 6:
		return r.DurationMs
	case 7:
		if r.DayStartAt == nil {
			return nil
		}
		return *r.DayStartAt
	case 8:
		if r.DayEndAt == nil {
			return nil
		}
		return *r.DayEndAt
	case 9:
		return r.DetectedAt
	}
	return nil
}

func attachWorkerHOSViolation(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*telematics.WorkerHOSViolation)(p)
	switch rel {
	case 0:
		r.Worker = (*worker.Worker)(child)
	}
}

